// @generated by @hexagen/sync

import path from "node:path";
import fs from "node:fs/promises";
import type { SyncConfig } from "../../config.js";
import type { ReportRecorder } from "../../domain/types.js";
import { createEmptyResult, type GeneratorResult } from "../../results.js";
import { safeWriteFileAtomic } from "../../fs-utils.js";
import { isExcludedDirectory } from "../../config/barrel-exclusions.js";
import {
  GENERATED_MARKER,
  isGeneratedFile,
  isSourceFile,
  generateBarrelContent,
  detectCircularExports,
  contentHash,
  type ExportEntry,
} from "./utils.js";

/**
 * Error thrown when circular exports are detected.
 * This is a critical failure that triggers abort + cleanup.
 */
export class CircularExportError extends Error {
  constructor(public readonly cycle: string[]) {
    super(`Circular export detected: ${cycle.join(" → ")}`);
    this.name = "CircularExportError";
  }
}

/**
 * Report of barrel generation operations.
 */
export interface BarrelGenerationReport {
  created: string[];
  updated: string[];
  skipped: string[];
  preserved: string[]; // Hand-written barrels that were not overwritten
  totalOps: number;
}

/**
 * Entry in the pending writes queue.
 * We collect all writes first, validate for circular exports, then write.
 */
interface PendingBarrelWrite {
  filePath: string;
  content: string;
  isNew: boolean;
}

/**
 * Recursively generate barrels for a package's src directory.
 *
 * Algorithm:
 * 1. Walk the directory tree depth-first
 * 2. For each directory with .ts files or subdirectories:
 *    - If index.ts exists and is NOT generated → skip (preserve hand-written)
 *    - If index.ts exists and IS generated → regenerate
 *    - If index.ts missing → create new barrel
 * 3. Collect all pending writes
 * 4. Validate for circular exports
 * 5. If circular detected → throw CircularExportError (critical failure)
 * 6. Write all barrels atomically
 *
 * @param moduleDir - Package root directory (e.g., packages/shared)
 * @param config - Sync configuration
 * @param report - Optional migration report for logging
 * @returns Generator result with created/updated/skipped counts
 * @throws CircularExportError if circular exports detected
 */
export async function generateRecursiveBarrels(
  moduleDir: string,
  config: SyncConfig,
  report?: ReportRecorder,
): Promise<GeneratorResult> {
  const result = createEmptyResult();
  const srcDir = path.join(moduleDir, "src");
  const layers = ["domain", "application", "infrastructure"];

  const pendingWrites: PendingBarrelWrite[] = [];
  const preserved: string[] = [];
  const exportGraph = new Map<string, string[]>();

  // Process each layer
  const layersWithContent: string[] = [];
  for (const layer of layers) {
    const layerDir = path.join(srcDir, layer);

    try {
      await fs.access(layerDir);
    } catch {
      // Layer directory doesn't exist, skip
      continue;
    }

    // Recursively walk the layer directory
    const layerExports = await walkDirectory(
      layerDir,
      pendingWrites,
      preserved,
      exportGraph,
      config,
    );
    if (layerExports.length > 0) layersWithContent.push(layer);
  }

  // Package-root barrel (`src/index.ts`) — EXTERNAL (API-driven) generation only.
  // Without it, `@{scope}/<pkg>` — which the base tsconfig `paths` map to
  // `<pkg>/src/index.ts` and which package.json's `main`/`exports` build from —
  // does not resolve, so every cross-package import in a generated project fails
  // (TS2307, #249).
  //
  // Gated to `mode === "external"` on purpose. In `self-regen` (this monorepo) the
  // package-root indexes are hand-maintained rich barrels: NAMED re-exports that
  // span non-layer directories (e.g. `errors/` → `Result`, `types/` → `Branded`)
  // and carry the `@generated` marker. A layer-only wildcard barrel would treat the
  // marker as "safe to regenerate" and clobber them, dropping every non-layer
  // export and breaking the build (caught by sync-integrity: `cli sync --force`
  // then `turbo run build`). Internal self-regen never emitted a package-root
  // barrel before, so scoping this to external preserves that behavior exactly.
  //
  // Re-export only layers that produced exportable content (mirrors the
  // dangling-export guard in walkDirectory). A hand-written `src/index.ts` is still
  // preserved via shouldGenerateBarrel; a previously-generated one regenerates
  // idempotently.
  if (config.mode === "external" && layersWithContent.length > 0) {
    const rootBarrelPath = path.join(srcDir, "index.ts");
    if (await shouldGenerateBarrel(rootBarrelPath, preserved, config.logger)) {
      const content = generateBarrelContent(
        layersWithContent.map((name) => ({ name, isDirectory: true })),
      );
      const existing = await readFileIfExists(rootBarrelPath);
      if (
        content !== null &&
        !(existing && contentHash(existing) === contentHash(content))
      ) {
        pendingWrites.push({
          filePath: rootBarrelPath,
          content,
          isNew: !existing,
        });
        exportGraph.set(
          rootBarrelPath,
          layersWithContent.map((name) => path.join(srcDir, name, "index.ts")),
        );
      }
    }
  }

  // Validate for circular exports before writing anything
  const circularCheck = detectCircularExports(exportGraph);
  if (circularCheck.hasCircular && circularCheck.cycle) {
    throw new CircularExportError(circularCheck.cycle);
  }

  // Write all pending barrels
  for (const pending of pendingWrites) {
    // Empty content signals deletion of empty barrel
    if (pending.content === "") {
      // RCA #3 (PR-A2): this unlink ran even under --dry-run, and the path
      // was miscounted into `created`. Dry-run now only records the intent;
      // both paths land in the `deleted` bucket.
      if (config.dryRun) {
        config.logger.info(
          `[DRY-RUN] would delete empty barrel ${pending.filePath}`,
        );
        result.deleted.push(pending.filePath);
        result.totalOps++;
        continue;
      }
      try {
        // PR-B1 (RCA #4): journal the pre-image before the unlink so a failed
        // run can restore the deleted barrel. The read-first also keeps the
        // ENOENT semantics identical to the bare unlink: a file that is
        // already gone short-circuits to the catch below either way.
        const preContent = await fs.readFile(pending.filePath, "utf8");
        config.journal?.recordDelete(pending.filePath, preContent);
        await fs.unlink(pending.filePath);
        result.deleted.push(pending.filePath);
        result.totalOps++;
        continue;
      } catch (err: unknown) {
        if (
          err &&
          typeof err === "object" &&
          "code" in err &&
          err.code === "ENOENT"
        ) {
          // File already deleted, skip
          continue;
        }
        throw err;
      }
    }

    const status = await safeWriteFileAtomic(
      pending.filePath,
      pending.content,
      config,
      report,
    );

    if (status === "created") {
      result.created.push(pending.filePath);
      result.totalOps++;
    } else if (status === "updated") {
      result.updated.push(pending.filePath);
      result.totalOps++;
    } else if (status === "skipped" || status === "protected") {
      result.skipped.push(pending.filePath);
    }
  }

  // Add preserved files to skipped (they were intentionally not modified)
  result.skipped.push(...preserved);

  return result;
}

/**
 * Recursively walk a directory and collect barrel generation tasks.
 */
async function walkDirectory(
  dirPath: string,
  pendingWrites: PendingBarrelWrite[],
  preserved: string[],
  exportGraph: Map<string, string[]>,
  config: SyncConfig,
): Promise<ExportEntry[]> {
  const { logger } = config;
  const exportEntries: ExportEntry[] = [];

  let entries;
  try {
    entries = await fs.readdir(dirPath, { withFileTypes: true });
  } catch {
    return exportEntries;
  }

  // Separate files and directories
  const files: string[] = [];
  const directories: string[] = [];

  for (const entry of entries) {
    if (isExcludedDirectory(entry.name)) {
      continue;
    }

    if (entry.isDirectory()) {
      directories.push(entry.name);
    } else if (entry.isFile() && isSourceFile(entry.name)) {
      files.push(entry.name.replace(/\.ts$/, ""));
    }
  }

  // Recursively process subdirectories first (depth-first)
  for (const dir of directories) {
    const subDirPath = path.join(dirPath, dir);
    const subExports = await walkDirectory(
      subDirPath,
      pendingWrites,
      preserved,
      exportGraph,
      config,
    );

    // Only add subdirectory to exports if it has exportable content
    // AND its barrel is not queued for deletion. `hasBarrel` probes the
    // filesystem, which still shows a stub index.ts we've already scheduled
    // for removal further down in `pendingWrites` (empty-content entries).
    // Without this guard the parent barrel would emit a dangling
    // `export * from "./<dir>/index.js";` that fails module resolution in
    // consumers after the write phase runs.
    const subBarrelPath = path.join(subDirPath, "index.ts");
    const isQueuedForDeletion = pendingWrites.some(
      (p) => p.filePath === subBarrelPath && p.content === "",
    );
    if (
      (subExports.length > 0 || (await hasBarrel(subDirPath))) &&
      !isQueuedForDeletion
    ) {
      exportEntries.push({ name: dir, isDirectory: true });
    }
  }

  // Add files to exports
  for (const file of files) {
    exportEntries.push({ name: file, isDirectory: false });
  }

  // Determine if we should create/update a barrel for this directory
  if (exportEntries.length === 0) {
    // No exportable content - check if there's an existing barrel to clean up
    const barrelPath = path.join(dirPath, "index.ts");
    const existingBarrel = await readFileIfExists(barrelPath);
    const dirName = path.basename(dirPath);
    const isLayerDir = ["domain", "application", "infrastructure"].includes(
      dirName,
    );

    if (existingBarrel) {
      // For layer directories: keep barrel with export {} (needed for TypeScript modules)
      // For other directories: can delete empty barrels
      const isGenerated = isGeneratedFile(existingBarrel);
      const isEmptyStub = existingBarrel.includes("export {}");

      if ((isGenerated || isEmptyStub) && !isLayerDir) {
        // Delete the empty barrel (not a layer directory)
        pendingWrites.push({
          filePath: barrelPath,
          content: "", // Empty content signals deletion
          isNew: false,
        });
      } else if (isEmptyStub && isLayerDir) {
        // Clean up comment-only barrels - replace with just export {}
        const newContent = `${GENERATED_MARKER}\n\nexport {};\n`;
        if (contentHash(existingBarrel) !== contentHash(newContent)) {
          pendingWrites.push({
            filePath: barrelPath,
            content: newContent,
            isNew: false,
          });
        }
      } else if (!existingBarrel.includes("export {}") && isLayerDir) {
        // Layer directory needs export {} to be a valid TypeScript module
        const newContent = `${GENERATED_MARKER}\n\nexport {};\n`;
        pendingWrites.push({
          filePath: barrelPath,
          content: newContent,
          isNew: false,
        });
      }
    } else if (isLayerDir) {
      // Create barrel with export {} for layer directories (valid TypeScript module)
      const newContent = `${GENERATED_MARKER}\n\nexport {};\n`;
      pendingWrites.push({
        filePath: barrelPath,
        content: newContent,
        isNew: true,
      });
    }
    return [];
  }

  const barrelPath = path.join(dirPath, "index.ts");
  const shouldCreateBarrel = await shouldGenerateBarrel(
    barrelPath,
    preserved,
    logger,
  );

  if (shouldCreateBarrel) {
    const content = generateBarrelContent(exportEntries);

    // Skip if content is null (empty directory)
    if (content === null) {
      return [];
    }

    // Check if content actually changed
    const existingContent = await readFileIfExists(barrelPath);
    if (
      existingContent &&
      contentHash(existingContent) === contentHash(content)
    ) {
      // Content unchanged, skip
      return exportEntries;
    }

    pendingWrites.push({
      filePath: barrelPath,
      content,
      isNew: !existingContent,
    });

    // Build export graph for circular detection
    // Map barrel path to the paths it exports (only directories have nested barrels)
    const exportPaths = exportEntries
      .filter((e) => e.isDirectory)
      .map((e) => path.join(dirPath, e.name, "index.ts"));
    exportGraph.set(barrelPath, exportPaths);
  }

  return exportEntries;
}

/**
 * Check if a directory has a barrel file.
 */
async function hasBarrel(dirPath: string): Promise<boolean> {
  try {
    await fs.access(path.join(dirPath, "index.ts"));
    return true;
  } catch {
    return false;
  }
}

/**
 * Determine if we should generate a barrel for the given path.
 *
 * Rules:
 * - If index.ts doesn't exist → create it
 * - If index.ts exists and is generated → update it
 * - If index.ts exists and is NOT generated → preserve it (add to preserved list)
 */
async function shouldGenerateBarrel(
  barrelPath: string,
  preserved: string[],
  logger: SyncConfig["logger"],
): Promise<boolean> {
  const content = await readFileIfExists(barrelPath);

  if (!content) {
    // File doesn't exist, create it
    return true;
  }

  if (isGeneratedFile(content)) {
    // File is generated, safe to update
    return true;
  }

  // File exists but is hand-written, preserve it
  preserved.push(barrelPath);
  logger.debug(`Preserving hand-written barrel: ${barrelPath}`);
  return false;
}

/**
 * Read file content if it exists, return null otherwise.
 */
async function readFileIfExists(filePath: string): Promise<string | null> {
  try {
    return await fs.readFile(filePath, "utf8");
  } catch (err: unknown) {
    if (
      err &&
      typeof err === "object" &&
      "code" in err &&
      err.code === "ENOENT"
    ) {
      return null;
    }
    throw err;
  }
}
